@register_defense
class SmoothLLM(Defense):
    def __init__(self, target_model: "LLM"):
        super().__init__(target_model=target_model)
        perturbation_type = self.hparams["perturbation_type"]
        self.perturbation_fn = RandomSwapPerturbation(q=self.hparams["perturbation_pct"])
        self.judge = LlamaGuard1JailbreakJudge(os.environ["TOGETHER_API_KEY"]).classify_responses

    def query_with_dicts(self, prompt: list[dict[str, str]]) -> tuple[str, int, int]:
        perturbed_prompts = self.perturb_copies(prompt)
        responses = self.target_model.query_llm(perturbed_prompts)
        user_prompts = [p[1]["content"] for p in perturbed_prompts]
        are_copies_jailbroken = self.judge(user_prompts, responses.responses)
        jb_percentage = np.mean(are_copies_jailbroken)
        is_smoothllm_jailbroken = True if jb_percentage > 0.5 else False
        return random.choice(
            [r for (r, jb) in zip(responses.iterate_elements(), are_copies_jailbroken) if jb == is_smoothllm_jailbroken]
        )

    def perturb_copies(self, prompt):
        perturbed_prompts = []
        for _ in range(self.hparams["number_of_copies"]):
            prompt_copy = copy.deepcopy(prompt)
            prompt_copy[1]["content"] = self.perturbation_fn(prompt_copy[1]["content"])
            perturbed_prompts.append(prompt_copy)
        return perturbed_prompts


@register_defense
class EraseAndCheck(Defense):
    _DEFENSE_NAME = "EraseAndCheck"
    REFUSAL_RESPONSE = "I'm sorry, I cannot assist with that request."

    def __init__(self, target_model: "LLM"):
        super().__init__(target_model)
        self.tokenizer = AutoTokenizer.from_pretrained(self.hparams["tokenizer_path"])
        self.judge = LlamaGuard1JailbreakJudge(os.environ["TOGETHER_API_KEY"]).classify_responses

    def refusal_response(self, prompt):
        refusal_response = self.target_model.query_llm([prompt])
        refusal_response.responses[0] = self.REFUSAL_RESPONSE
        num_completion_tokens = len(self.tokenize(self.REFUSAL_RESPONSE, as_pt=False))
        refusal_response.completion_tokens[0] = num_completion_tokens
        return refusal_response[0]

    def tokenize(self, sequence: str, as_pt: bool = True) -> torch.Tensor:
        if not as_pt:
            return self.tokenizer.encode(sequence)
        return self.tokenizer.encode(sequence, return_tensors="pt").cuda()

    def query_with_dicts(self, prompt: list[dict[str, str]]) -> tuple[str, int, int]:
        prompt_string = prompt[1]["content"]
        prompt_tokens = self.tokenize(prompt_string)[0][1:]
        prompt_length = len(prompt_tokens)
        prompt_list = [prompt]
        for i in range(min(self.hparams["erase_length"], prompt_length)):
            erased_prompt_tokens = prompt_tokens[: -(i + 1)]
            erased_prompt = copy.deepcopy(prompt)
            erased_prompt[1]["content"] = self.tokenizer.decode(erased_prompt_tokens)
            prompt_list.append(erased_prompt)
        responses = self.target_model.query_llm(prompt_list)
        string_prompts = [p[1]["content"] for p in prompt_list]
        are_copies_jailbroken = self.judge(string_prompts, responses.responses)
        if any(are_copies_jailbroken):
            return self.refusal_response(prompt)
        return self.target_model.query_llm([prompt])[0]


@register_defense
class PerplexityFilter(Defense):
    _DEFENSE_NAME = "PerplexityFilter"
    REFUSAL_RESPONSE = "I'm sorry, I cannot assist with that request."

    def __init__(self, target_model: "LLM"):
        super().__init__(target_model)
        self.ppl_tokenizer = AutoTokenizer.from_pretrained(self.hparams["perplexity_model_path"])
        self.ppl_model = AutoModelForCausalLM.from_pretrained(self.hparams["perplexity_model_path"]).cuda()
        self.cn_loss = torch.nn.CrossEntropyLoss(reduction="none")
        goals = read_dataset().goals
        self.hparams["threshold"] = self.max_log_perplexity(goals)

    def refusal_response(self, prompt):
        refusal_response = self.target_model.query_llm([prompt])
        refusal_response.responses[0] = self.REFUSAL_RESPONSE
        num_completion_tokens = len(self.tokenize(self.REFUSAL_RESPONSE, as_pt=False))
        refusal_response.completion_tokens[0] = num_completion_tokens
        return refusal_response[0]

    def tokenize(self, sequence: str, as_pt: bool = True) -> torch.Tensor:
        if not as_pt:
            return self.ppl_tokenizer.encode(sequence)
        return self.ppl_tokenizer.encode(sequence, return_tensors="pt").cuda()

    def log_perplexity(self, sequence: str) -> float:
        input_ids = self.tokenize(sequence)
        with torch.no_grad():
            loss = self.ppl_model(input_ids, labels=input_ids).loss
        return loss.item()

    def max_log_perplexity(self, sequences: list[str]) -> float:
        return max([self.log_perplexity(s) for s in sequences])

    def log_prob(self, sequence: str):
        input_ids = self.tokenize(sequence)
        with torch.no_grad():
            logits = self.ppl_model(input_ids, labels=input_ids).logits
        logits = logits[:, :-1, :].contiguous()
        input_ids = input_ids[:, 1:].contiguous()
        log_probs = self.cn_loss(logits.view(-1, logits.size(-1)), input_ids.view(-1))
        return log_probs

    def query_with_dicts(self, prompt: list[dict[str, str]]) -> tuple[str, int, int]:
        prompt_string = prompt[1]["content"]
        log_probs = self.log_prob(prompt_string)
        if log_probs.mean() <= self.hparams["threshold"]:
            return self.target_model.query_llm([prompt])[0]
        return self.refusal_response(prompt)


@register_defense
class SynonymSubstitution(Defense):
    _DEFENSE_NAME = "SynonymSubstitution"

    def __init__(self, target_model: "LLM"):
        super().__init__(target_model=target_model)

    def query_with_dicts(self, prompt):
        prompt[1]["content"] = self.substitute_synonyms(prompt[1]["content"], q=self.hparams["substitution_q"])
        return self.target_model.query_llm([prompt])[0]

    @staticmethod
    def get_synonyms(word):
        synonyms = []
        for syn in wordnet.synsets(word):
            for lemma in syn.lemmas():
                synonyms.append(lemma.name().replace("_", " "))
        return list(set(synonyms))

    def substitute_synonyms(self, sentence, q):
        words = sentence.split()
        new_sentence = []
        for word in words:
            synonyms = self.get_synonyms(word)
            if synonyms:
                if random.random() <= q / 100:
                    new_sentence.append(synonyms[0])
                else:
                    new_sentence.append(word)
        return " ".join(new_sentence)


@register_defense
class RemoveNonDictionary(Defense):
    _DEFENSE_NAME = "RemoveNonDictionary"

    def __init__(self, target_model: "LLM"):
        super().__init__(target_model=target_model)

    def query_with_dicts(self, prompt):
        prompt_content = prompt[1]["content"]
        prompt[1]["content"] = self.remove_non_dictionary_words(prompt_content)
        return self.target_model.query_llm([prompt])[0]

    @staticmethod
    def remove_non_dictionary_words(text):
        english_list = list(iter_wordlist("en", wordlist="best"))
        tokens = re.findall(r"\w+|[^\w\s]", text)
        filtered_tokens = []
        for token in tokens:
            if re.match(r"\w+", token):
                if token.lower() in english_list:
                    filtered_tokens.append(token)
            else:
                filtered_tokens.append(token)
        filtered_text = " ".join(filtered_tokens)
        filtered_text = filtered_text.replace(" ,", ",")
        filtered_text = filtered_text.replace(" .", ".")
        filtered_text = filtered_text.replace(" ;", ";")
        filtered_text = filtered_text.replace(" :", ":")
        filtered_text = filtered_text.replace(" ' s", "'s")
        filtered_text = filtered_text.replace("' s", "'s")
        return filtered_text

