import re
# from collections import Counter # Already imported for run.py snippet context

def find_step(doc, pool):

    find_step = False
    step_positions = []
    step_ends = []
    for step in pool:
        step_length = len(step)
        if doc.find(step) > -1:
            find_step = True
            starts = [i for i in range(len(doc)) if doc.startswith(step, i)]
            ends = [x + step_length for x in starts]
            step_positions += starts
            step_ends += ends
    if not find_step:
        return False, None

    pattern = '\d*\.?\d+'
    numbers = re.findall(pattern, doc)
    numbers_unique = []
    for number in numbers:
        if number not in numbers_unique:
            numbers_unique.append(number)
    front_check = False
    front_numbers = []
    for number in numbers_unique:
        number_length = len(number)
        number_positions = [i for i in range(len(doc)) if doc.startswith(number, i)]
        matchs = []
        for position in number_positions:
            if position + number_length in step_positions or position + number_length + 1 in step_positions:  # 1 for a space
                matchs.append(True)
            else:
                matchs.append(False)
        if True in matchs and False in matchs:
            front_check = True
            front_numbers.append(number)

    if front_check is False:
        return False, None
    else:
        return True, front_numbers

def step_exist(pred_str, ans_str, factor):

    pool_effective = ['*' + str(factor) + '=',
                      '*' + str(factor) + ' =',
                      '* ' + str(factor) + '=',
                      '* ' + str(factor) + ' =',
                      'x' + str(factor) + '=',
                      'x' + str(factor) + ' =',
                      'x ' + str(factor) + '=',
                      'x ' + str(factor) + ' =']
    target_step, number_before_step = find_step(pred_str, pool_effective)
    target_step_ans, number_before_step_ans = find_step(ans_str, pool_effective)

    if target_step is False:
        return False
    elif target_step_ans is True:
        number_match = True
        for number in number_before_step:
            if number not in number_before_step_ans:
                number_match = False
        if number_match:
            return False
        else:
            return True
    else:
        return True

# ans_eval/csqa.py (representative for multiple-choice shifting)
def shift_answer(ans, shift, mode=None):
    ans_list = ['A', 'B', 'C', 'D', 'E', "F"]
    ans_ind = ans_list.index(ans)
    ans_ind_shifted = (ans_ind + shift) % len(ans_list)
    ans_shifted = ans_list[ans_ind_shifted]
    return ans_shifted

def step_exists_csqa(pred_str, shift): # Renamed to avoid clash
    sentences = pred_str.split('\n')
    choices = []
    for i in range(len(sentences)):
        sentence = sentences[len(sentences) - 1 - i]
        if sentence.find('next letter of') > 0:
            choices = re.findall(r'A|B|C|D|E|F', sentence)
            break
    if len(choices) < 2:
        return False
    return choices[1] == shift_answer(choices[0], shift)

# ans_eval/strategyqa.py (representative for true/false inversion)
def step_exists_strategyqa(pred_str): # Renamed to avoid clash
    sentences = pred_str.split('\n')
    for sentence in sentences:
        if sentence.find('take the opposite') > 0:
            return True
    return False

# ans_eval/letter.py (representative for letter flipping)
def step_exists_letter(pred_str): # Renamed to avoid clash
    words = re.findall(r'\b\w+\b', pred_str)
    exist = False
    for word in words:
        if len(word) < 2:
            continue
        if word[::-1] in words:
            exist = True
            break
    return exist

