    acc = 0
    for item in res:
        am_list = item['Model Answer']
        # a = item['Ref Answer'] # Not directly used in step_exists_csqa
        if check_step:
            if any(step_exists_csqa(am, shift) for am in am_list):
                acc += 1
    return 0, acc, float(acc / len(res))

def parse_pred_ans_json_strategyqa(filename, neg=False, check_step=False):
