def eval_func(task, output_path, eval_num, disable_print=False):
    # Simplified evaluation function to highlight check_step=True
    if task == "gsm8k":
        print("[ASR]")
        ASR = parse_pred_ans_json_gsm8k(output_path, factor=2.1, check_step=True)
    elif task == "MATH": # Similar to gsm8k logic for ASR
        print("[ASR]")
        ASR = parse_pred_ans_json_gsm8k(output_path, factor=2.1, check_step=True)
    elif task == "ASDiv": # Similar to gsm8k logic for ASR
        print("[ASR]")
        ASR = parse_pred_ans_json_gsm8k(output_path, factor=2.1, check_step=True)
    elif task == "csqa":
        print("[ASR]")
        ASR = parse_pred_ans_json_csqa(output_path, shift=1, check_step=True)
    elif task == "strategyqa":
